import { Extension } from '@tiptap/core'
import { sanitizeHtmlString } from './sanitize'

/**
 * Sanitizes raw HTML from .md files at the markdown-it renderer boundary,
 * BEFORE the rendered string is handed to a DOMParser. This ordering is
 * essential: <script> in raw HTML can execute when the string is parsed into
 * a live DOM. Cleaning the token content first removes that vector entirely.
 *
 * Only html_block / html_inline tokens (raw HTML authored in the document)
 * are touched; all other tokens are generated by markdown-it and are safe.
 */
export const MarkdownSanitizer = Extension.create({
  name: 'markdownSanitizer',

  addStorage() {
    return {
      markdown: {
        parse: {
          setup(md: {
            renderer: {
              rules: Record<string, (tokens: Array<{ content: string }>, idx: number) => string>
            }
          }) {
            const sanitizeRule =
              (original: (tokens: Array<{ content: string }>, idx: number) => string) =>
              (tokens: Array<{ content: string }>, idx: number): string =>
                sanitizeHtmlString(original(tokens, idx))

            md.renderer.rules.html_block = sanitizeRule(md.renderer.rules.html_block)
            md.renderer.rules.html_inline = sanitizeRule(md.renderer.rules.html_inline)
          }
        }
        // No serialize hook: we don't rewrite the user's .md file. Sanitized
        // content is safe to persist as-is.
      }
    }
  }
})
